local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local MazeMgr = import('Game.Maze.MazeMgr'):GetInstance()
local cs_coroutine = import('XLua.cs_coroutine')
local UIRaycastBlocker = CS.Engine.UI.UIRaycastBlocker.Instance

------------ import ------------

------------ define ------------

------------ define ------------


---@class PatrolMainChooseNode
---@field AnimBoss                      	UnityEngine.Animator
---@field Boss                          	UnityEngine.RectTransform
---@field BtnEvent                      	UnityEngine.RectTransform
---@field LayoutBtn                     	UnityEngine.RectTransform
local PatrolMainChooseNode = Class("PatrolMainChooseNode")
function PatrolMainChooseNode:__init()
    self.btnAction = nil
    self.btnNodeMap = {}
    self.isBoss = false

end

function PatrolMainChooseNode:__delete()
    self.btnAction = nil
    self.btnNodeMap = nil
    self.isBoss = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function PatrolMainChooseNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function PatrolMainChooseNode:Awake()
    self.EventEnterChoose = Events.AddListener(Constants.EventNames.PatrolEventChoose, Bind(self, self.PlayChooseAnim))

    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end
end

function PatrolMainChooseNode:FreshBaseUI()
    local isBoss = table.count(MazeMgr.currentInfo) == 1 and checkNumber(MazeMgr.currentInfo["1"].type) == 3
    self.isBoss = isBoss
    KTool.SetActive(self.Boss, isBoss)

    KTool.SetActive(self.LayoutBtn, not isBoss)
    local chooseAnimTime = CfUtils.GetAnimatorTime(self.AnimBoss, "PatrolMainDialog_BtnSelect")
    SetButtonAction(self.Boss, function ()
        cs_coroutine.start(function()
            UIRaycastBlocker:AddCondition("PatrolMainChooseNode")
            CfUtils.PlayAnimator(self.AnimBoss, "Select")
            cs_coroutine.yield_return(chooseAnimTime)
            MazeMgr:BtnActionShowEventPanel(1)
            UIRaycastBlocker:RemoveCondition("PatrolMainChooseNode")
        end)
    end)
    if not isBoss then
        local currentData = MazeMgr.currentInfo
        local goCount = self.LayoutBtn.transform.childCount - 1 --减去默认prefab的数量
        if goCount > #currentData then
            for i = #currentData + 1, goCount do --复用时隐藏多出来的
                KTool.SetActive(self.btnNodeMap[tostring(i)], false)
            end
        end
        for i = 1, table.count(currentData) do
            local go
            local k = checkString(i)
            local v = currentData[k]
            go = self.btnNodeMap[k]
            if not go then
                go = CfUtils.InstantiateGo(self.BtnEvent, self.LayoutBtn.gameObject)
                go.name = "btnNode"..k
                self.btnNodeMap[k] = go.gameObject
            end
            local goEnv = CfUtils.GetLuaScr(go, "Game.UI.Patrol.PatrolMainChooseCellNode")
            local typeData = CfUtils.GetCfVo(AutoIds.IdSetting351, "PatrolPointTypeVo",v.type)
            local btnData = {
                iconPath = typeData.icon,
                text = typeData.name,
                index = checkNumber(k),
            }
            goEnv:FreshBaseUI(btnData)
            goEnv:SetBtnCallBack(function ()
                cs_coroutine.start(function()
                    UIRaycastBlocker:AddCondition("PatrolMainChooseNode")
                    cs_coroutine.yield_return(chooseAnimTime)
                    MazeMgr:BtnActionShowEventPanel(k)
                    UIRaycastBlocker:RemoveCondition("PatrolMainChooseNode")
                end)
            end)
            KTool.SetActive(go, true)
        end
    end
end

function PatrolMainChooseNode:FreshSelectStatus(isSelected)

end

function PatrolMainChooseNode:PlayChooseAnim(index)
    if isNull(index) and self.isBoss then
        self.AnimBoss:Play("PatrolMainDialog_BtnBoss")
    end
end

function PatrolMainChooseNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.PatrolEventChoose, self.EventEnterChoose)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PatrolMainChooseNode